select * from asset_usage_record


        and asset_id = #{assetId}


        and user_name like concat('%', #{userName}, '%')


        and department like concat('%', #{department}, '%')


        and status = #{status}


        and usage_start_time >= #{beginTime}


        and usage_start_time <= #{endTime}


order by usage_start_time desc, create_time desc
